```jsx
import React, { useEffect, useState } from "react";
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from "recharts";
import { supabase } from "../lib/supabase";       // adjust path to your Supabase client
import { buildQuery } from "../lib/queryBuilder"; // adjust path to your query builder

const VoltageChart = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      const towndata = buildQuery("towndatamarch_1_2");

      // Build query: select all where House_id = 20, ordered by timestamp
      let query = towndata.select("*");
      query = towndata.filters.eq("House_id", 20)(query);
      query = towndata.order("timestamp", true)(query);

      const { data, error } = await query;

      if (error) {
        console.error("Supabase error:", error);
      } else {
        setData(data);
      }

      setLoading(false);
    };

    fetchData();
  }, []);

  if (loading) return <div>Loading voltage data...</div>;
  if (data.length === 0) return <div>No data found for House 20.</div>;

  return (
    <ResponsiveContainer width="100%" height={300}>
      <LineChart data={data}>
        <CartesianGrid strokeDasharray="3 3" />
        <XAxis dataKey="timestamp" tickFormatter={(t) => new Date(t).toLocaleTimeString()} />
        <YAxis domain={["auto", "auto"]} label={{ value: "Voltage (V)", angle: -90, position: "insideLeft" }} />
        <Tooltip labelFormatter={(t) => new Date(t).toLocaleString()} />
        <Legend />
        <Line type="monotone" dataKey="Voltage.PhA" name="Phase A" stroke="#8884d8" dot={false} />
        <Line type="monotone" dataKey="Voltage.PhB" name="Phase B" stroke="#82ca9d" dot={false} />
        <Line type="monotone" dataKey="Voltage.PhC" name="Phase C" stroke="#ffc658" dot={false} />
      </LineChart>
    </ResponsiveContainer>
  );
};

export default VoltageChart;
```

