import React, { useState } from "react";
import data from "../data.json"; // adjust path

const ReactiveTable = () => {
  const options = ["dogs", "cats"];
  const [selectedCategory, setSelectedCategory] = useState("dogs");

  // Get the current data array
  const currentData = data[selectedCategory] || [];

  return (
    <div className="w-full max-w-md mx-auto p-4 bg-white shadow rounded-lg">
      {/* Dropdown */}
      <div className="mb-4">
        <label className="mr-2 font-medium">Select category:</label>
        <select
          value={selectedCategory}
          onChange={(e) => setSelectedCategory(e.target.value)}
          className="border rounded p-1"
        >
          {options.map((opt) => (
            <option key={opt} value={opt}>
              {opt.charAt(0).toUpperCase() + opt.slice(1)}
            </option>
          ))}
        </select>
      </div>

      {/* Table */}
      <table className="w-full border-collapse">
        <thead>
          <tr>
            {currentData.length > 0 &&
              Object.keys(currentData[0]).map((key) => (
                <th
                  key={key}
                  className="border px-2 py-1 text-left bg-gray-100"
                >
                  {key.charAt(0).toUpperCase() + key.slice(1)}
                </th>
              ))}
          </tr>
        </thead>
        <tbody>
          {currentData.map((item, idx) => (
            <tr key={idx} className="hover:bg-gray-50">
              {Object.values(item).map((val, i) => (
                <td key={i} className="border px-2 py-1">
                  {val}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>

      {currentData.length === 0 && <p>No data available.</p>}
    </div>
  );
};

export default ReactiveTable;
```

---

### 3️⃣ How it works

1. **Dropdown**: lets you pick a category (`dogs` or `cats`).  
2. **State**: `selectedCategory` updates when the dropdown changes.  
3. **Dynamic table**: reads from `data.json` based on `selectedCategory` and displays the corresponding array.  
4. **Automatic columns**: table headers are generated from the keys of the first object in the selected array.  

---

